87	// assertReconnectHealthLine checks the single output line is the exact one
88	// produced from the seq-10 record alone. A selector driven by receive order,
89	// newest collection time, whole-second display, or field splicing would
90	// differ: the fresh seq-5 record would show status=online, version=1.26.0
91	// (no skew), height=900 and missed=2 (no alarm at tolerance 4).
92	func assertReconnectHealthLine(t *testing.T, out, errOut string, code int) {
93		t.Helper()
94		if code != 0 {
95			t.Fatalf("offline is a successful query and must exit 0, got %d: stderr=%q", code, errOut)
96		}
97		if errOut != "" {
98			t.Errorf("health findings belong on stdout; stderr must be empty, got %q", errOut)
99		}
100		lines := outputLines(out)
101		if len(lines) != 1 {
102			t.Fatalf("want exactly one health line, got %d: %q", len(lines), out)
103		}
104		if lines[0] != reconnectLatestLine {
105			t.Errorf("health line = %q\nwant            %q", lines[0], reconnectLatestLine)
106		}
107	}
