109	// TestCLIHealthReplayedRecordsGreatestSeqDrivesStatus saves the same two
110	// records in both arrival orders and requires the byte-identical health line,
111	// built entirely from the greatest seq.
112	func TestCLIHealthReplayedRecordsGreatestSeqDrivesStatus(t *testing.T) {
113		var seen []string
114		for _, seed := range []struct {
115			name string
116			fn   func(*testing.T, string)
117		}{
118			{"stale greatest seq received first", seedReconnectStored},
119			{"stale greatest seq received last", seedReconnectReversed},
120		} {
121			t.Run(seed.name, func(t *testing.T) {
122				dir := t.TempDir()
123				seed.fn(t, dir)
124				out, errOut, code := healthQueryAt(t, dir, cliQueryAt,
125					"--node", reconnectNode, "--expected-version", "1.26.0", "--tolerated-misses", "4")
126				assertReconnectHealthLine(t, out, errOut, code)
127				seen = append(seen, out)
128	
129				// History keeps both gapped seqs ascending, each intact.
130				lines := historyLines(t, dir, reconnectNode)
131				if len(lines) != 2 {
132					t.Fatalf("history = %q, want two records", lines)
133				}
134				if lines[0] != "node=backfill seq=5 collected_at=2026-10-01T11:59:50Z version=1.26.0 height=900 missed=2" {
135					t.Errorf("history line 1 = %q", lines[0])
136				}
137				if lines[1] != "node=backfill seq=10 collected_at=2026-10-01T11:58:00Z version=1.25.0 height=1000 missed=5" {
138					t.Errorf("history line 2 = %q", lines[1])
139				}
140			})
141		}
142		if len(seen) == 2 && seen[0] != seen[1] {
143			t.Errorf("arrival order changed the output:\n%s\nvs\n%s", seen[0], seen[1])
144		}
145	}
