278	// TestCLIHealthBaselineKeepsGreatestSeqAndCumulative checks that a
279	// missed-since baseline changes only the missed-duty alarm basis: the latest
280	// record is still seq 10 with its stale time (offline), version skew and
281	// cumulative missed=5 on the first line; the baseline seq 5 contributes only
282	// the second line. It must never decide online status.
283	func TestCLIHealthBaselineKeepsGreatestSeqAndCumulative(t *testing.T) {
284		dir := t.TempDir()
285		seedReconnectStored(t, dir)
286	
287		// new missed = 5-2 = 3, tolerance 2: alarm; status is still offline.
288		out, errOut, code := healthQueryAt(t, dir, cliQueryAt,
289			"--node", reconnectNode, "--expected-version", "1.26.0",
290			"--tolerated-misses", "2", "--missed-since-seq", "5")
291		if code != 0 {
292			t.Fatalf("baseline query must exit 0, got %d: %q", code, errOut)
293		}
294		lines := outputLines(out)
295		if len(lines) != 2 {
296			t.Fatalf("want two lines, got %q", out)
297		}
298		wantFirst := "node=backfill status=offline seq=10 collected_at=2026-10-01T11:58:00Z version=1.25.0 height=1000 missed=5 findings=[offline version skew: 1.25.0 != 1.26.0 missed duties above tolerance]"
299		if lines[0] != wantFirst {
300			t.Errorf("first line = %q\nwant          %q", lines[0], wantFirst)
301		}
302		if strings.Contains(lines[0], "missed=2") {
303			t.Errorf("first line must show cumulative missed=5, not the baseline count: %q", lines[0])
304		}
305		if lines[1] != "baseline_seq=5 baseline_missed=2 new_missed=3 tolerated_misses=2" {
306			t.Errorf("second line = %q", lines[1])
307		}
308	
309		// new=3 with tolerance 3 silences the miss alarm but leaves offline and
310		// the seq-10 version skew untouched: the baseline does not decide status.
311		out, _, code = healthQueryAt(t, dir, cliQueryAt,
312			"--node", reconnectNode, "--expected-version", "1.26.0",
313			"--tolerated-misses", "3", "--missed-since-seq", "5")
314		if code != 0 {
315			t.Fatalf("exit=%d out=%q", code, out)
316		}
317		lines = outputLines(out)
318		wantFirst = "node=backfill status=offline seq=10 collected_at=2026-10-01T11:58:00Z version=1.25.0 height=1000 missed=5 findings=[offline version skew: 1.25.0 != 1.26.0]"
319		if lines[0] != wantFirst {
320			t.Errorf("first line with silent miss alarm = %q\nwant                                %q", lines[0], wantFirst)
321		}
322		if lines[1] != "baseline_seq=5 baseline_missed=2 new_missed=3 tolerated_misses=3" {
323			t.Errorf("second line = %q", lines[1])
324		}
325	
326		// Baseline equal to the latest record: new missed 0, still offline.
327		out, _, code = healthQueryAt(t, dir, cliQueryAt,
328			"--node", reconnectNode, "--expected-version", "1.26.0",
329			"--tolerated-misses", "0", "--missed-since-seq", "10")
330		if code != 0 {
331			t.Fatalf("exit=%d out=%q", code, out)
332		}
333		lines = outputLines(out)
334		if !strings.Contains(lines[0], "status=offline") || !strings.Contains(lines[0], "seq=10") {
335			t.Errorf("baseline==latest must stay offline on seq 10: %q", lines[0])
336		}
337		if lines[1] != "baseline_seq=10 baseline_missed=5 new_missed=0 tolerated_misses=0" {
338			t.Errorf("second line = %q", lines[1])
339		}
340	}
